#pragma once
#include "Wire.h"
template<>struct Wire<TS_PRODUCT>;
template<>struct Wire<TS_CHALLENGE>;
template<>struct Wire<TS_TOKEN>;
template<>struct Wire<TS_STATUS>;
template<>struct Wire<TS_PRODUCT> {static Json Encode(const TS_PRODUCT& v){Json j=Json::object();j["product"]=EncodeWire(v.product);j["reserved"]=EncodeWire(v.reserved);return j;}static void Decode(const Json& j,TS_PRODUCT& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="product")DecodeWire(it.value(),v.product);else if(it.key()=="reserved")DecodeWire(it.value(),v.reserved);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<TS_CHALLENGE> {static Json Encode(const TS_CHALLENGE& v){Json j=Json::object();j["magic"]=EncodeWire(v.magic);j["version"]=EncodeWire(v.version);j["product"]=EncodeWire(v.product);j["permission"]=EncodeWire(v.permission);j["nonce"]=EncodeWire(v.nonce);return j;}static void Decode(const Json& j,TS_CHALLENGE& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="magic")DecodeWire(it.value(),v.magic);else if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="product")DecodeWire(it.value(),v.product);else if(it.key()=="permission")DecodeWire(it.value(),v.permission);else if(it.key()=="nonce")DecodeWire(it.value(),v.nonce);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<TS_TOKEN> {static Json Encode(const TS_TOKEN& v){Json j=Json::object();j["grant"]=EncodeWire(v.grant);j["signature"]=EncodeWire(v.signature);return j;}static void Decode(const Json& j,TS_TOKEN& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="grant")DecodeWire(it.value(),v.grant);else if(it.key()=="signature")DecodeWire(it.value(),v.signature);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<TS_STATUS> {static Json Encode(const TS_STATUS& v){Json j=Json::object();j["version"]=EncodeWire(v.version);j["product"]=EncodeWire(v.product);j["mode"]=EncodeWire(v.mode);j["reserved"]=EncodeWire(v.reserved);j["remaining_100ns"]=EncodeWire(v.remaining_100ns);j["elapsed_100ns"]=EncodeWire(v.elapsed_100ns);return j;}static void Decode(const Json& j,TS_STATUS& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="product")DecodeWire(it.value(),v.product);else if(it.key()=="mode")DecodeWire(it.value(),v.mode);else if(it.key()=="reserved")DecodeWire(it.value(),v.reserved);else if(it.key()=="remaining_100ns")DecodeWire(it.value(),v.remaining_100ns);else if(it.key()=="elapsed_100ns")DecodeWire(it.value(),v.elapsed_100ns);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
